/**
 * Test flows for verifying that trigger input defaults are properly applied
 * when fields are not explicitly specified in Fluent code.
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Test 1: Only mandatory fields specified - all others should use defaults
export const testTriggerWithOnlyMandatoryFields = Flow(
    {
        $id: Now.ID['test_trigger_defaults_mandatory_only'],
        name: 'Test Trigger Defaults - Mandatory Only',
        description: 'Flow with only mandatory trigger fields to test default value application',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_defaults_mandatory_only_trigger'] },
        {
            table: 'incident',
        }
    ),
    (__params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_trigger_defaults_mandatory_only_log'] },
            {
                log_level: 'info',
                log_message: 'Testing trigger defaults',
            }
        )
    }
)

// Test 2: Some optional fields specified - unspecified ones should use defaults
export const testTriggerWithPartialFields = Flow(
    {
        $id: Now.ID['test_trigger_defaults_partial'],
        name: 'Test Trigger Defaults - Partial Fields',
        description: 'Flow with some optional fields to ensure unspecified ones get defaults',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_defaults_partial_trigger'] },
        {
            table: 'incident',
            condition: 'priority=1',
            run_flow_in: 'foreground',
            // run_on_extended, run_when_setting, run_when_user_setting NOT specified
            // These should get their default values
        }
    ),
    (__params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_trigger_defaults_partial_log'] },
            {
                log_level: 'info',
                log_message: 'Testing partial trigger defaults',
            }
        )
    }
)

// Test 3: Explicitly set non-default values - should use provided values, not defaults
export const testTriggerWithExplicitNonDefaults = Flow(
    {
        $id: Now.ID['test_trigger_explicit_non_defaults'],
        name: 'Test Trigger Explicit Non-Defaults',
        description: 'Flow with explicitly set non-default values',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_explicit_non_defaults_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_on_extended: 'true', // Non-default (default is 'false')
            run_when_setting: 'interactive', // Non-default (default is 'both')
            run_when_user_setting: 'not_one_of', // Non-default (default is 'any')
            run_flow_in: 'background',
            run_when_user_list: [],
        }
    ),
    (__params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_trigger_explicit_non_defaults_log'] },
            {
                log_level: 'info',
                log_message: 'Testing explicit non-default values',
            }
        )
    }
)
